"use client"

import * as React from "react"
import { motion, useReducedMotion, type Transition } from "motion/react"

import { cn } from "@/lib/utils"

import {
  NextjsIcon,
  ReactIcon,
  TailwindIcon,
  TypescriptIcon,
} from "./icons"

export type OrbitConfig = {
  id: number
  /** Orbit diameter as a factor of `size` (can exceed 1). */
  radiusFactor: number
  /** Seconds per full rotation. */
  speed: number
  icon: React.ReactNode
  iconSize: number
  orbitColor?: string
  orbitThickness?: number
}

export type BeamCircleProps = {
  /** Overall stage diameter in px. Default 300. */
  size?: number
  orbits?: OrbitConfig[]
  /** Node in the center hub. Defaults to the Next.js mark. */
  centerIcon?: React.ReactNode
  className?: string
}

export {
  NextjsIcon,
  ReactIcon,
  TailwindIcon,
  TypescriptIcon,
  type TechIconProps,
} from "./icons"

const DEFAULT_ORBITS: OrbitConfig[] = [
  {
    id: 1,
    radiusFactor: 0.15,
    speed: 7,
    icon: <ReactIcon />,
    iconSize: 22,
    orbitColor: "color-mix(in oklab, var(--primary) 35%, transparent)",
    orbitThickness: 1.5,
  },
  {
    id: 2,
    radiusFactor: 0.35,
    speed: 12,
    icon: <TypescriptIcon />,
    iconSize: 26,
    orbitThickness: 1.5,
  },
  {
    id: 3,
    radiusFactor: 0.55,
    speed: 9,
    icon: <TailwindIcon />,
    iconSize: 28,
    orbitColor: "rgba(14, 215, 181, 0.4)",
    orbitThickness: 2,
  },
  {
    id: 4,
    radiusFactor: 0.75,
    speed: 15,
    icon: <NextjsIcon />,
    iconSize: 32,
    orbitThickness: 1,
  },
]

function rotationTransition(
  duration: number,
  reduceMotion: boolean | null
): Transition {
  if (reduceMotion) {
    return { duration: 0 }
  }
  return {
    repeat: Infinity,
    duration,
    ease: "linear",
  }
}

export function BeamCircle({
  size = 300,
  orbits: customOrbits,
  centerIcon,
  className,
}: BeamCircleProps) {
  const reduceMotion = useReducedMotion()
  const orbitsData = customOrbits ?? DEFAULT_ORBITS
  const halfSize = size / 2
  const hubSize = halfSize * 0.2

  return (
    <div
      className={cn(
        "flex items-center justify-center bg-transparent",
        className
      )}
    >
      <div className="relative" style={{ width: size, height: size }}>
        {orbitsData.map((orbit) => {
          const orbitDiameter = size * orbit.radiusFactor
          const orbitRadius = orbitDiameter / 2

          return (
            <React.Fragment key={orbit.id}>
              <div
                aria-hidden
                className={cn(
                  "absolute rounded-full border border-dashed",
                  !orbit.orbitColor && "border-foreground/30"
                )}
                style={{
                  width: orbitDiameter,
                  height: orbitDiameter,
                  top: halfSize - orbitRadius,
                  left: halfSize - orbitRadius,
                  borderColor: orbit.orbitColor,
                  borderWidth: orbit.orbitThickness ?? 1,
                }}
              />

              <motion.div
                className="absolute inset-0"
                style={{ width: size, height: size }}
                animate={reduceMotion ? undefined : { rotate: 360 }}
                transition={rotationTransition(orbit.speed, reduceMotion)}
              >
                <div
                  className="absolute"
                  style={{
                    top: halfSize,
                    left: halfSize + orbitRadius,
                    transform: "translate(-50%, -50%)",
                  }}
                >
                  <motion.div
                    className="grid place-content-center rounded-full border border-border/70 bg-card shadow-soft"
                    style={{
                      width: orbit.iconSize,
                      height: orbit.iconSize,
                    }}
                    animate={reduceMotion ? undefined : { rotate: -360 }}
                    transition={rotationTransition(orbit.speed, reduceMotion)}
                  >
                    {React.isValidElement(orbit.icon)
                      ? React.cloneElement(
                          orbit.icon as React.ReactElement<{ size?: number }>,
                          { size: orbit.iconSize * 0.7 }
                        )
                      : orbit.icon}
                  </motion.div>
                </div>
              </motion.div>
            </React.Fragment>
          )
        })}

        <div className="absolute inset-0 z-10 grid place-content-center">
          <motion.div
            className="grid place-content-center rounded-full border border-border/70 bg-card shadow-soft"
            style={{ width: hubSize, height: hubSize }}
            animate={
              reduceMotion ? undefined : { scale: [1, 1.1, 1] }
            }
            transition={
              reduceMotion
                ? { duration: 0 }
                : { repeat: Infinity, duration: 2, ease: "easeInOut" }
            }
          >
            {centerIcon ?? (
              <NextjsIcon size={Math.max(14, halfSize * 0.1)} />
            )}
          </motion.div>
        </div>
      </div>
    </div>
  )
}

export default BeamCircle

"use client"

import * as React from "react"
import { useId } from "react"

import { cn } from "@/lib/utils"

import type { TechIconProps } from "./react"

export function TailwindIcon({
  className,
  size = 16,
  ...props
}: TechIconProps) {
  const uid = useId().replace(/:/g, "")
  const grad = `${uid}-grad`

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 600 600"
      width={size}
      height={size}
      aria-hidden="true"
      className={cn("shrink-0", className)}
      {...props}
    >
      <defs>
        <linearGradient
          id={grad}
          x1="0"
          y1="120"
          x2="600"
          y2="480"
          gradientUnits="userSpaceOnUse"
        >
          <stop stopColor="#2298BD" />
          <stop offset="1" stopColor="#0ED7B5" />
        </linearGradient>
      </defs>
      <path
        fill={`url(#${grad})`}
        d="M300 120q-120 0-150 120 45-60 105-45c22.8 5.7 39.1 22.3 57.2 40.6C341.6 265.4 375.6 300 450 300q120 0 150-120-45 60-105 45c-22.8-5.7-39.1-22.3-57.2-40.6C408.4 154.6 374.4 120 300 120M150 300Q30 300 0 420q45-60 105-45c22.8 5.7 39.1 22.3 57.2 40.6C191.6 445.4 225.6 480 300 480q120 0 150-120-45 60-105 45c-22.8-5.7-39.1-22.3-57.2-40.6C258.4 334.6 224.4 300 150 300"
      />
    </svg>
  )
}
